        // Breaking change 1: Cosmos provider no longer supports indexes (they are
        // managed server-side). Remove HasIndex calls or the model build throws.

        // Breaking change 2: Discriminator property renamed from "Discriminator"
        // to "$type" in EF Core 9. Map it back for existing documents.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 3: id property format changed from "EntityType|Key" to
        // just the key value in EF Core 9. Opt in to the legacy format for
        // existing documents.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<LegacyCosmosIdGenerator>();
    }
}
