using Microsoft.EntityFrameworkCore;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // BREAKING CHANGE 1 – HasIndex() removed (Cosmos manages indexes server-side).
        // FIX: Delete the HasIndex call entirely. (was: .HasIndex(b => b.Name))

        // BREAKING CHANGE 2 – Discriminator property renamed "$type" → was "Discriminator".
        // Existing documents still carry "Discriminator". Map it back explicitly.
        modelBuilder.Entity<Blog>()
            .HasDiscriminator<string>("Discriminator")
            .HasValue<Blog>("Blog");

        // BREAKING CHANGE 3 – id value no longer prefixed with "EntityType|".
        // Existing documents have id = "Blog|1". Map the entity's Id property
        // directly to the JSON "id" so EF reads/writes the stored value as-is.
        modelBuilder.Entity<Blog>()
            .Property(b => b.Id)
            .ToJsonProperty("id");

        // BREAKING CHANGE 4 – Raw SQL queries referencing c.Discriminator still
        // work only because we kept the old property name above. No SQL changes needed.
        // If the rename had NOT been reverted, every query like
        //   SELECT * FROM c WHERE c.Discriminator = 'Blog'
        // would need to change to:
        //   SELECT * FROM c WHERE c["$type"] = 'Blog'
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

